/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Exports the contents of a grid (using the selected order and filters) to an Excel file. LoadWWPContext.Call(&WWPContext)
Do 'OpenDocument'
&CellRow = 1 &FirstColumn = 1
Do 'LoadGridState'
Do 'WriteFilters'
Do 'WriteColumnTitles'
Do 'WriteData'
Do 'CloseDocument'
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
Sub 'OpenDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&Random = Random() * 10000 &Filename = WWP_GetDefaultExportPath() + !"trnsconvqtdeWWExport-" + &Random.ToString().Trim() + !".xlsx"
&ExcelDocument.Open(&Filename) Do 'CheckStatus' &ExcelDocument.Clear()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteFilters'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If &GridState.DynamicFilters.Count >= 1 &GridStateDynamicFilter = &GridState.DynamicFilters.Item(1) &DynamicFiltersSelector1 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector1 = !'UNICONORIGEMDESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &uniConOrigemDescricao1.FromString(&GridStateDynamicFilter.Value) If not &uniConOrigemDescricao1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&uniConOrigemDescricao1) EndIf Case &DynamicFiltersSelector1 = !'UNICONDESTINODESCRICAO' &DynamicFiltersOperator1 = &GridStateDynamicFilter.Operator &uniConDestinoDescricao1.FromString(&GridStateDynamicFilter.Value) If not &uniConDestinoDescricao1.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator1 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator1 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&uniConDestinoDescricao1) EndIf EndCase If &GridState.DynamicFilters.Count >= 2 &DynamicFiltersEnabled2 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(2) &DynamicFiltersSelector2 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector2 = !'UNICONORIGEMDESCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &uniConOrigemDescricao2.FromString(&GridStateDynamicFilter.Value) If not &uniConOrigemDescricao2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&uniConOrigemDescricao2) EndIf Case &DynamicFiltersSelector2 = !'UNICONDESTINODESCRICAO' &DynamicFiltersOperator2 = &GridStateDynamicFilter.Operator &uniConDestinoDescricao2.FromString(&GridStateDynamicFilter.Value) If not &uniConDestinoDescricao2.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator2 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator2 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&uniConDestinoDescricao2) EndIf EndCase If &GridState.DynamicFilters.Count >= 3 &DynamicFiltersEnabled3 = True &GridStateDynamicFilter = &GridState.DynamicFilters.Item(3) &DynamicFiltersSelector3 = &GridStateDynamicFilter.Selected Do Case Case &DynamicFiltersSelector3 = !'UNICONORIGEMDESCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &uniConOrigemDescricao3.FromString(&GridStateDynamicFilter.Value) If not &uniConOrigemDescricao3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&uniConOrigemDescricao3) EndIf Case &DynamicFiltersSelector3 = !'UNICONDESTINODESCRICAO' &DynamicFiltersOperator3 = &GridStateDynamicFilter.Operator &uniConDestinoDescricao3.FromString(&GridStateDynamicFilter.Value) If not &uniConDestinoDescricao3.IsEmpty() &CellRow += 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn).Color = 3 Do Case Case &DynamicFiltersOperator3 = 0 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterLike") Case &DynamicFiltersOperator3 = 1 &ExcelDocument.Cells(&CellRow, &FirstColumn).Text = format('%1 (%2)', "Descrição", "WWP_FilterContains") EndCase &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Italic = True &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&uniConDestinoDescricao3) EndIf EndCase EndIf EndIf EndIf If not (&TFuniConOrigemDescricao_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Unidade Origem") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFuniConOrigemDescricao_Sel) Else If not (&TFuniConOrigemDescricao.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Unidade Origem") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFuniConOrigemDescricao) EndIf EndIf If not (&TFuniConDestinoDescricao_Sel.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Unidade Destino ") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFuniConDestinoDescricao_Sel) Else If not (&TFuniConDestinoDescricao.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Unidade Destino ") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Text = WWP_Export_SecureText(&TFuniConDestinoDescricao) EndIf EndIf If not (&TFuniConvQtdeGerar.IsEmpty() AND &TFuniConvQtdeGerar_To.IsEmpty()) WWP_ExportWriteFilter(&ExcelDocument, true, &CellRow, &FirstColumn, "Qtde a Gerar") &ExcelDocument.Cells(&CellRow, &FirstColumn + 1).Number = &TFuniConvQtdeGerar WWP_ExportWriteFilter(&ExcelDocument, false, &CellRow, &FirstColumn + 2, "WWP_TSTo") &ExcelDocument.Cells(&CellRow, &FirstColumn + 3).Number = &TFuniConvQtdeGerar_To EndIf &CellRow += 2
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteColumnTitles'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&VisibleColumnCount = 0 If &Session.Get(!'trnsconvqtdeWWColumnsSelector') <> '' &ColumnsSelectorXML = &Session.Get(!'trnsconvqtdeWWColumnsSelector') &ColumnsSelector.FromXml(&ColumnsSelectorXML) Else Do 'InitializeColumnsSelector' EndIf
&ColumnsSelector.Columns.Sort(!'Order') For &ColumnsSelector_Column in &ColumnsSelector.Columns If &ColumnsSelector_Column.IsVisible = True &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = GetMessageText(iif(&ColumnsSelector_Column.DisplayName.IsEmpty(), &ColumnsSelector_Column.ColumnName, &ColumnsSelector_Column.DisplayName)) &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Bold = True &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Color = 11 &VisibleColumnCount += 1 EndIf EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'WriteData'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
For each trnsconvqtde order uniConOrigemDescricao when &OrderedBy = 1 AND &OrderedDsc = False order (uniConOrigemDescricao) when &OrderedBy = 1 AND &OrderedDsc = True order uniConDestinoDescricao when &OrderedBy = 2 AND &OrderedDsc = False order (uniConDestinoDescricao) when &OrderedBy = 2 AND &OrderedDsc = True order uniConvQtdeGerar when &OrderedBy = 3 AND &OrderedDsc = False order (uniConvQtdeGerar) when &OrderedBy = 3 AND &OrderedDsc = True
using trnsconvqtdeWWDS(&DynamicFiltersSelector1, &DynamicFiltersOperator1, &uniConOrigemDescricao1, &uniConDestinoDescricao1, &DynamicFiltersEnabled2, &DynamicFiltersSelector2 , &DynamicFiltersOperator2, &uniConOrigemDescricao2, &uniConDestinoDescricao2, &DynamicFiltersEnabled3, &DynamicFiltersSelector3, &DynamicFiltersOperator3 , &uniConOrigemDescricao3, &uniConDestinoDescricao3, &TFuniConOrigemDescricao, &TFuniConOrigemDescricao_Sel, &TFuniConDestinoDescricao, &TFuniConDestinoDescricao_Sel , &TFuniConvQtdeGerar, &TFuniConvQtdeGerar_To) Where prefCodigo = &prefCodigo
// Write cell values &CellRow += 1
Do 'BeforeWriteLine' &VisibleColumnCount = 0 For &ColumnsSelector_Column in &ColumnsSelector.Columns If &ColumnsSelector_Column.IsVisible = True Do Case Case &ColumnsSelector_Column.ColumnName = !'uniConOrigemDescricao' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(uniConOrigemDescricao) Case &ColumnsSelector_Column.ColumnName = !'uniConDestinoDescricao' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Text = WWP_Export_SecureText(uniConDestinoDescricao) Case &ColumnsSelector_Column.ColumnName = !'uniConvQtdeGerar' &ExcelDocument.Cells(&CellRow, &FirstColumn + &VisibleColumnCount).Number = uniConvQtdeGerar EndCase &VisibleColumnCount += 1 EndIf EndFor
Do 'AfterWriteLine'
Endfor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CloseDocument'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ExcelDocument.Save() Do 'CheckStatus' &ExcelDocument.Close() &Session.Set(!'WWPExportFilePath', &Filename) &Session.Set(!'WWPExportFileName', !"trnsconvqtdeWWExport.xlsx") &Filename = WWP_DownloadReport.Link()
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'CheckStatus'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
If (&ExcelDocument.ErrCode <> 0) &Filename = "" &ErrorMessage = &ExcelDocument.ErrDescription &ExcelDocument.Close() Return EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'InitializeColumnsSelector'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
&ColumnsSelector = new WWPColumnsSelector() WWP_ColumnsSelector_Add(&ColumnsSelector, !"uniConOrigemDescricao", '', !'Unidade Origem', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"uniConDestinoDescricao", '', !'Unidade Destino ', True, '') WWP_ColumnsSelector_Add(&ColumnsSelector, !"uniConvQtdeGerar", '', !'Qtde a Gerar', True, '')
&UserCustomValue = LoadColumnsSelectorState.Udp(!'trnsconvqtdeWWColumnsSelector') If not(&UserCustomValue.IsEmpty()) &ColumnsSelectorAux.FromXml(&UserCustomValue) WWP_ColumnSelector_UpdateColumns(&ColumnsSelectorAux, &ColumnsSelector) EndIf
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'LoadGridState'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
// Load grid state from session. If &Session.Get(!"trnsconvqtdeWWGridState") = !"" &GridState.FromXml(LoadGridState.Udp(!"trnsconvqtdeWWGridState")) Else &GridState.FromXml(&Session.Get(!"trnsconvqtdeWWGridState")) Endif
&OrderedBy = &GridState.OrderedBy &OrderedDsc = &GridState.OrderedDsc
For &GridStateFilterValue in &GridState.FilterValues Do Case Case &GridStateFilterValue.Name = !"TFUNICONORIGEMDESCRICAO" &TFuniConOrigemDescricao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFUNICONORIGEMDESCRICAO_SEL" &TFuniConOrigemDescricao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFUNICONDESTINODESCRICAO" &TFuniConDestinoDescricao.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFUNICONDESTINODESCRICAO_SEL" &TFuniConDestinoDescricao_Sel.FromString(&GridStateFilterValue.Value) Case &GridStateFilterValue.Name = !"TFUNICONVQTDEGERAR" &TFuniConvQtdeGerar.FromString(&GridStateFilterValue.Value) &TFuniConvQtdeGerar_To.FromString(&GridStateFilterValue.ValueTo) EndCase EndFor
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'BeforeWriteLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub
Sub 'AfterWriteLine'
/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
EndSub

	/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */

parm(out:&Filename, out:&ErrorMessage);

	/* Generated by DVelop Work With Plus Pattern [End] - Do not change */
